-- ============================================================
-- 生产工单 演示数据（MES / 生产管理 阶段二）
-- 由 docs/scripts/gen_workorder_data.py 生成，请勿手工修改
--
-- 覆盖：9 张工单 + 42 行工单用料
--   状态分布：PREPARE 待下达 / CONFIRMED 已下达 / FINISHED 已完工 / CANCELED 已取消
--   类型分布：SELF 自产 / OUTSOURCE 外协 / PURCHASE 外购
--   来源分布：ORDER 客户订单 / STORE 库存备货
--
-- 执行方式（必须带 utf8mb4，否则中文乱码）：
--   mysql -uroot -proot --default-character-set=utf8mb4 mes_elevn < mes-workorder-data.sql
--
-- 回滚（只删演示数据，不动自己手工测的数据）：
--   delete from pro_workorder_bom where remark like '下达自动展开%' and workorder_id between 1001 and 1999;
--   delete from pro_workorder where remark like '演示数据%' and workorder_id between 1001 and 1999;
-- ============================================================

-- 幂等：先清掉上一次生成的演示数据
delete from pro_workorder_bom where workorder_id between 1001 and 1999;
delete from pro_workorder where workorder_id between 1001 and 1999;

-- ---------- pro_workorder 生产工单 ----------

-- ---------- pro_workorder_bom 工单用料（有制程按制程BOM展开，否则按产品BOM） ----------

-- ---------- 数据核对 ----------
-- 按状态统计
select status, count(*) as cnt from pro_workorder
  where workorder_id between 1001 and 1999 group by status;
-- 按类型 x 来源统计（检查三条业务规则的分支是否都覆盖到）
select workorder_type, order_source, count(*) as cnt from pro_workorder
  where workorder_id between 1001 and 1999 group by workorder_type, order_source;
-- 工单 + 用料行数
select w.workorder_code, w.workorder_type, w.order_source, w.status,
       count(b.line_id) as bom_lines
  from pro_workorder w
  left join pro_workorder_bom b on b.workorder_id = w.workorder_id and b.del_flag = '0'
 where w.workorder_id between 1001 and 1999
 group by w.workorder_id order by w.workorder_code;
